<script setup>
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import MapPanel from '../components/MapPanel.vue'
import {rooms,money} from '../data'
import {state,toggleFavorite} from '../store'
const route=useRoute(),router=useRouter(),room=computed(()=>[...rooms,...state.posts].find(r=>r.id===route.params.id)),slide=ref(0),contact=ref(false)
function act(kind){if(!state.user)return router.push('/dang-nhap?redirect='+encodeURIComponent(route.fullPath));if(kind==='save')toggleFavorite(room.value.id);else contact.value=true}
</script>
<template><div class="container page" v-if="room"><RouterLink to="/tim-tro" class="back-link"><Icon name="back" :size="18"/> Quay lại tìm trọ</RouterLink><div class="detail-grid"><section><div class="detail-photo"><img :src="slide===0?room.image:'/illustrations/room-'+(slide+1)+'.svg'" :alt="room.title+' — góc nhìn '+(slide+1)"><button class="icon-button photo-prev" aria-label="Ảnh trước" @click="slide=(slide+3)%4"><Icon name="left"/></button><button class="icon-button photo-next" aria-label="Ảnh tiếp theo" @click="slide=(slide+1)%4"><Icon name="right"/></button><span class="photo-counter">{{slide+1}} / 4 · Hình minh họa</span></div><div class="section-heading detail-title"><div><span class="badge">{{room.status}}</span><h1>{{room.title}}</h1><p class="muted location"><Icon name="pin" :size="17"/>{{room.address}}</p></div><button class="icon-button outlined" @click="act('save')" aria-label="Lưu bài đăng"><Icon name="heart"/></button></div><p class="detail-price">{{money(room.price)}}<span>/ tháng</span></p><div class="spec-grid"><div><Icon name="area"/><span>Diện tích<strong>{{room.area}} m²</strong></span></div><div><Icon name="users"/><span>Số người tối đa<strong>{{room.people}} người</strong></span></div><div><Icon name="calendar"/><span>Giờ giấc<strong>Tự do</strong></span></div></div><div class="cost-grid"><p>Tiền nước<strong>{{money(room.water)}} / m³</strong></p><p>Tiền điện<strong>{{money(room.electric)}} / kWh</strong></p><p>Tiền cọc<strong>{{money(room.deposit)}}</strong></p></div><section class="detail-section"><h2>Tiện ích</h2><div class="amenity-grid"><span v-for="a in room.amenities" :key="a"><Icon name="check" :size="18"/>{{a}}</span></div></section><section class="detail-section"><h2>Mô tả & quy định</h2><p>{{room.desc}}</p><p>Tôn trọng không gian chung, giữ vệ sinh và hạn chế tiếng ồn sau 22 giờ.</p></section><section class="contact-card"><div class="inline"><span class="avatar">MA</span><div><h3>Người liên hệ</h3><p class="muted">{{room.house}} · Dữ liệu minh họa</p></div></div><div class="inline"><button class="button primary" @click="act('contact')"><Icon name="phone" :size="18"/>Xem thông tin liên hệ</button><button class="button secondary" @click="act('chat')">Chat Zalo</button></div><p v-if="contact" class="notice">Đây là phòng mẫu. Chức năng liên hệ thực tế sẽ hoạt động khi kết nối dữ liệu chủ trọ.</p></section></section><aside><h2>Vị trí</h2><MapPanel :label="room.house" :address="room.address"/><a class="map-external" :href="'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(room.address)" target="_blank" rel="noopener">Mở khu vực trên Google Maps <Icon name="external" :size="15"/></a><section class="detail-section"><h2>Nhà trọ</h2><img class="house-preview" :src="room.image" :alt="room.house"><h3>{{room.house}}</h3><p class="muted">{{room.address}}</p></section><section class="detail-section"><h2>Đánh giá</h2><div class="review"><strong>Nguyễn Minh Anh</strong><div class="stars">★★★★★</div><p>Phòng thoáng, khu vực đi lại thuận tiện, phù hợp cho sinh viên.</p><small class="muted">Đánh giá mẫu trong bản demo</small></div></section><div class="notice"><Icon name="shield"/><p>Hãy xem phòng trực tiếp và kiểm tra hợp đồng trước khi đặt cọc.</p></div></aside></div></div><div v-else class="container empty-state"><h1>Không tìm thấy phòng</h1><RouterLink to="/tim-tro" class="button primary">Về tìm trọ</RouterLink></div></template>
